// ❌ OLD: Removing the table from the DOM, but storing a reference
// to one single child button in a global cache array pins the entire
// table tree (millions of bytes) in memory.
const buttonCache = [];

function createAndRemoveTable() {
  const table = document.createElement('table');
  for (let i = 0; i < 5000; i++) {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>Row ${i}</td><td><button>Click</button></td>`;
    table.appendChild(tr);
  }
  document.body.appendChild(table);

  // Cache just one button:
  buttonCache.push(table.querySelector('button'));

  // Remove table from DOM:
  table.remove(); 
  // ❌ LEAK: 'table' is detached, but buttonCache -> button -> parentNode -> table
  // keeps all 5000 rows in memory.
}

// ✅ NEW: Ensure no references to any element or descendant survive
// component teardown, allowing the Oilpan/V8 GC to sweep the entire tree.
let buttonCache = [];

function createAndRemoveTable() {
  const table = document.createElement('table');
  for (let i = 0; i < 5000; i++) {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>Row ${i}</td><td><button>Click</button></td>`;
    table.appendChild(tr);
  }
  document.body.appendChild(table);

  // Use WeakRef / WeakSet if ephemeral tracking is required, or clear:
  const button = table.querySelector('button');

  // Clean removal:
  buttonCache = null;
  table.remove();
  // ✅ GC successfully sweeps all nodes on next major cycle.
}
